import pages as PG
from pages import *
from pages import foreword,glance,reading,story,cards,end,sources,build,covart,verse
from fx import *
PG.configure('/subramanya/',[('skanda','Who Is Skanda?','The Six-Faced Son of Śiva'),('shashthi','The Ṣaṣṭhī Story','Skanda Ṣaṣṭhī and Subrahmaṇya Ṣaṣṭhī'),('kukke','Kukke Subrahmaṇya','The Serpent’s Refuge'),('ghati','Ghāṭi Subrahmaṇya','The Twin Images on the Hill')],'navy','Subrahmaṇya Ṣaṣṭhī','Lord','Subrahmaṇya Ṣaṣṭhī')
PG.OUT='outd/sub/'
i=1
def vel(): return '<path d="M0 0 v-70" stroke="#6a4a2a" stroke-width="3"/><path d="M0 -70 q-10 -10 0 -30 q10 20 0 30z" fill="#dfe6ee"/>'
def skanda(): return god('#c0392b')+g(16,0,.7,vel())
def peacock(): return '<ellipse cy="-14" rx="12" ry="8" fill="#1d6fb8"/><path d="M8 -18 q6 -14 4 -24" stroke="#1d6fb8" stroke-width="4" fill="none"/><path d="M-10 -14 q-30 -10 -34 -30 q20 0 34 22z" fill="#2a9d6f"/>'+''.join(f'<circle cx="{-30+k*6}" cy="{-30+k*3}" r="2.5" fill="#e0a800"/>' for k in range(4))
def rooster(): return '<ellipse cy="-12" rx="10" ry="8" fill="#c98a3a"/><circle cx="8" cy="-22" r="5" fill="#c98a3a"/><path d="M8 -28 l2 -6 l3 6" fill="#c0392b"/><path d="M-10 -14 q-10 -14 -4 -24" stroke="#2a6a3a" stroke-width="4" fill="none"/>'
def mango_tree(): return '<path d="M0 0 v-40" stroke="#6a4a2a" stroke-width="8"/><ellipse cy="-56" rx="30" ry="22" fill="#2f7a3a"/>'+''.join(f'<ellipse cx="{x}" cy="{y}" rx="3" ry="4" fill="#e0a800"/>' for x,y in [(-12,-50),(8,-60),(16,-46)])
def anthill(): return '<path d="M-40 0 q10 -30 20 -40 q8 -26 20 -30 q12 4 20 30 q10 10 20 40z" fill="#b5651d"/><circle cy="-30" r="5" fill="#3a2a1a"/>'
def chariot(): return '<path d="M-30 0 h60 l-10 -40 h-40z" fill="#c98a3a"/><path d="M-24 -40 l24 -40 l24 40" fill="#c0392b"/><circle cx="-20" cy="2" r="8" fill="#6a4a2a"/><circle cx="20" cy="2" r="8" fill="#6a4a2a"/>'
def reeds(): return ''.join(f'<path d="M{x} 0 q{(-1)**x*4} -30 0 -60" stroke="#7a9a3a" stroke-width="3" fill="none"/>' for x in range(-30,32,6))
COV=covart('Skanda on his peacock holding the vel, a rooster banner beside him, a split mango tree on one side and a temple chariot on the other',f'<rect width="440" height="196" fill="#e3eaf3"/>'+'<rect y="170" width="440" height="26" fill="#c9d6e6"/>'+g(220,180,1.4,peacock())+g(220,150,1.2,skanda())+g(300,120,1,rooster())+g(80,186,1.1,mango_tree())+g(370,186,1.1,chariot()))
pp=[foreword(i,['Skanda was born for a war. On the sixth day of the bright fortnight, the tradition says, he finished it: the demon king was struck down, and from his body came the peacock Skanda rides and the rooster on his flag. That sixth day, <b>Ṣaṣṭhī</b>, became his.','Tamil Nadu keeps <b>Skanda Ṣaṣṭhī</b> in Aippasi with six days of fasting and the great Sūrasaṃhāram on the beach at Tiruccendūr. A month later Karnataka and the Telugu lands keep <b>Subrahmaṇya Ṣaṣṭhī</b> in Mārgaśīrṣa, remembering his wedding, with chariots at Kukke and milk at the cobra’s anthill. This part tells the war in full, explains the two Ṣaṣṭhīs, gives two verses from Śaṅkara’s Subrahmaṇya Bhujaṅgam, and shows how the day is kept.'],[('z','Two Ṣaṣṭhīs for one god?'),('b','Two regions, two months, one victory, Zappy. Tamil Nadu remembers the war; Karnataka remembers the wedding and the serpent.')]),
 glance([('Ṣaṣṭhī','The sixth lunar day; every bright Ṣaṣṭhī is sacred to Skanda'),('Skanda Ṣaṣṭhī','Tamil Nadu, Sri Lanka, Malaysia: Ṣaṣṭhī of Aippasi (Kārttika lunar), after six days of fasting'),('Subrahmaṇya Ṣaṣṭhī','Karnataka, Andhra, Telaṅgāṇa: Ṣaṣṭhī of Mārgaśīrṣa (Nov–Dec); also Campā Ṣaṣṭhī, Kukke Ṣaṣṭhī, Subbarāyana Ṣaṣṭhī'),('Story','Victory over Tāraka and, in the Tamil telling, Śūrapadma; then the wedding with Devasenā'),('Big events','Sūrasaṃhāram at Tiruccendūr; the Brahmaratha at Kukke'),('Practice','Fasting, milk at anthills and nāga stones, feeding a boy as Kumāra, temple chariots'),('Next','Ghāṭi Subrahmaṇya’s chariot on the Ṣaṣṭhī of Puṣya')],svg(560,140,'Skanda with peacock and anthill',f'<rect width="560" height="140" fill="#e3eaf3"/>'+g(200,130,1.1,peacock())+g(200,104,1,skanda())+g(380,130,1,anthill())+g(480,130,.8,chariot()))),
 reading('which','WHICH ṢAṢṬHĪ IS WHICH?','Three names, three months',svg(560,150,'Three calendar markers for Aippasi, Mārgaśīrṣa and Puṣya',f'<rect width="560" height="150" fill="#fffaf0"/>'+''.join(g(x,110,1,skanda())+lab(x,138,t) for x,t in [(120,'Aippasi: Tamil'),(280,'Mārgaśīrṣa: Karnataka'),(440,'Puṣya: Ghāṭi')])),['<b>Monthly.</b> Every bright Ṣaṣṭhī is a small fast for Skanda, all year round.','<b>Skanda Ṣaṣṭhī (Kanda Ṣaṣṭi).</b> In Aippasi (October–November) Tamil Nadu, Sri Lanka and Malaysia keep six days: the war on the sixth, the wedding on the seventh.','<b>Subrahmaṇya Ṣaṣṭhī.</b> In Mārgaśīrṣa (November–December), Karnataka and the Telugu states keep the next Ṣaṣṭhī: almanacs call it the Ṣaṣṭhī after Sūrasaṃhāram. The same day in Maharashtra is <b>Campā Ṣaṣṭhī</b>, ending the six-day festival of Khaṇḍobā at Jejuri, a form of Śiva. Why “Campā”? Often said to be for the campaka flower; explanations differ.','<b>Puṣya Ṣaṣṭhī.</b> The month after, '+L('/subramanya/ghati/','Ghāṭi Subrahmaṇya')+' holds its chariot festival.'],[('z','So Kukke Ṣaṣṭhī and Jejuri’s Campā Ṣaṣṭhī fall on one day?'),('b','Yes, Zappy. Śiva’s son at Kukke, Śiva himself as Khaṇḍobā at Jejuri: one family, one day.')],'One god, <b>three Ṣaṣṭhīs</b>.'),
 reading('six','WHY THE SIXTH DAY?','Sixes everywhere',svg(560,150,'Six small faces in a ring around a spear',f'<rect width="560" height="150" fill="#e3eaf3"/>'+g(280,130,1,vel())+''.join(f'<circle cx="{280+60*__import__("math").cos(k*1.047):.1f}" cy="{70+40*__import__("math").sin(k*1.047):.1f}" r="12" fill="#f2c79b" stroke="#111" stroke-width="1.5"/>' for k in range(6))),['<b>Six mothers.</b> The child born of Śiva’s fire was nursed by the six Kṛttikās, the Pleiades; he grew six faces, one for each mother: <b>Ṣaṇmukha</b>, <b>Kārttikeya</b>. His birth is told in '+L('/subramanya/skanda/','Part 1')+'.','<b>Six syllables, six abodes.</b> His name <i>Śaravaṇabhava</i>, “born in the reed-pond”, has six syllables; Tamil Nadu’s six great shrines are the <b>Āṟupaṭai Vīṭu</b>.','<b>Six days of war.</b> In the Tamil telling the battle with Śūrapadma lasts six days and ends on Ṣaṣṭhī.','<b>Six enemies.</b> A common teaching: the vel destroys the six inner foes (<i>ṣaḍripu</i>): desire, anger, greed, delusion, pride and envy. It is a teaching built on the story, very popular in Ṣaṣṭhī sermons; read it as a meaning, not a fact.'],[('z','Is the six-enemies idea in the Purāṇa?'),('b','It’s a teaching built on the story, Zappy. Read it as a meaning, not a fact.')],'Six faces, <b>six days</b>.'),
 story('general','THE GENERAL OF THE GODS','A boy takes command',strip('Three panels: the child in the reeds; the gods giving him the spear; the boy-general marching with the army',[panel([(reeds(),1),(baby(),.7)],'#e3f5e9',150),panel([(devi(sari='#2a9d6f',items=('lotus',)),.8),(vel(),1),(child(),.8)],'#fff3cf',150),panel([(skanda(),.9),(god(),.7),(god('#e0a800'),.7)],'#e3eaf3',150)],['the reed child','the gift of the vel','the march']),'Skanda Purāṇa and Śiva Purāṇa; the Tamil Kanda Purāṇam for the southern telling.',['The child of the reeds grew in six days into a young warrior.','The gods made him <b>Devasenāpati</b>, commander of their army. Each gave a gift: Pārvatī the spear, the <b>vel</b>; others weapons, a banner, a mount.','With the gods behind him, Kumāra marched against the demons.','In the Tamil telling, <b>Śūrapadma</b> ruled with his brothers <b>Siṃhamukha</b>, lion-faced, and <b>Tāraka</b>, elephant-faced.','Skanda first sent his commander <b>Vīrabāhu</b> to offer peace. Śūrapadma refused.'],[('z','He offered peace first?'),('b','Always, Zappy. Even the general of the gods sends a messenger before the spear.')],'Peace offered <b>before war</b>.'),
 story('taraka','TĀRAKA AND THE KRAUÑCA HILL','The first victory',strip('Three panels: Tāraka hiding behind a mountain; the vel thrown; the mountain pierced and Tāraka fallen',[panel([(demon('#5a3a6a'),.9),(mountain('#8a7a6a',False),.8)],'#e9e3f5',150),panel([(skanda(),.9),(vel(),.8)],'#fff3cf',150),panel([(mountain('#8a7a6a',False),.8),(vel(),.7)],'#fde4e4',150)],['behind the hill','the spear','pierced through']),'Purāṇic and Tamil tellings; details vary.',['<b>Tāraka</b> fought with every trick of illusion and hid behind the mountain <b>Krauñca</b>, which his ally guarded.','Skanda hurled his vel. It pierced the Krauñca mountain right through and killed Tāraka.','Old texts remember Skanda as <b>Krauñcabhettā</b>, “the piercer of Krauñca”. In some tellings Krauñca is a demon ally of Tāraka.','Brahmā’s boon held: only Śiva’s son could kill Tāraka, and he did.','The Tamil Kanda Purāṇam goes on: Siṃhamukha falls next, and then the king, Śūrapadma.'],[('z','The spear went through a mountain?'),('b','The vel is knowledge, many teachers say, Zappy: nothing hides from it.')],'The spear that <b>pierced the mountain</b>.'),
 story('surapadma','ŚŪRAPADMA AND THE MANGO TREE','Pride split in two',strip('Three panels: the demon king changing forms; a great mango tree standing in the sea; the tree split, one half a peacock, the other a rooster',[panel([(demon('#2a3a5a'),1)],'#fde4e4',150),panel([(river(144,130,'#5a8ab8'),1),(mango_tree(),.9)],'#dfe9f6',None),panel([(peacock(),1),(rooster(),1)],'#fff3cf',150)],['form after form','the mango tree','peacock and rooster']),'The Tamil Kanda Purāṇam’s climax.',['The war raged for six days. One by one, Śūrapadma’s sons and brothers fell.','On the last day the demon king took one form after another to escape. At last he became a huge <b>mango tree</b> standing in the sea.','Skanda hurled his vel and split the tree in two.','Even then he did not destroy him: one half became the <b>peacock</b> he rides, the other the <b>rooster</b> on his banner.','The enemy is not killed but turned into a servant. Many read it as the ego, split and tamed, carrying the god. (Interpretation.)'],[('z','He spared the worst demon?'),('b','He spared what was left after the pride was gone, Zappy. That’s the Ṣaṣṭhī lesson.')],'The enemy <b>becomes the vehicle</b>.'),
 reading('sura','SŪRASAṂHĀRAM','The war re-enacted on the beach',svg(560,170,'On a beach, a procession image of Skanda facing a tall demon effigy, with crowds and the sea',f'<rect width="560" height="170" fill="#fde9c8"/>'+'<path d="M0 120 q280 -20 560 0 v50 h-560z" fill="#e9d6c0"/><path d="M0 100 q280 -16 560 0 v20 h-560z" fill="#8fb8de"/>'+g(200,150,1.3,skanda())+g(360,150,1.6,demon('#2a3a5a'))+''.join(g(x,165,.6,person(c)) for x,c in [(60,'#c0392b'),(90,'#e0a800'),(470,'#2a5aa8'),(500,'#2a9d6f')])),['<b>Where.</b> <b>Tiruccendūr</b>, Murugan’s seashore abode, where he camped for the war, on the evening of Skanda Ṣaṣṭhī, the sixth day of the Aippasi festival.','<b>What.</b> Murugan’s festival image meets effigies of the demon on the beach; the demon keeps changing heads (elephant, lion, his own) and each is “cut off”; finally the tree, and the peacock and rooster.','<b>Next day.</b> <b>Tirukkalyāṇam</b>, Murugan’s wedding with Devasenā.','<b>The fast.</b> Many devotees fast for all six days, some on one meal, some on milk and fruit; others keep it on Ṣaṣṭhī alone. The same rite is kept in Murugan temples across Tamil Nadu, Sri Lanka, Malaysia and Singapore.'],[('z','The demon changes heads?'),('b','Pride keeps changing masks, Zappy. The vel keeps finding it.')],'The war <b>on the beach</b>.'),
 story('wedding','THE WEDDING AT KUMĀRA PARVATA','Karnataka’s Ṣaṣṭhī',strip('Three panels: Skanda and Gaṇeśa arriving at a hill in the Western Ghāṭs; Indra giving his daughter Devasenā; rivers flowing together',[panel([(skanda(),.9),(ganesha(seat=False),.6),(mountain('#6a8a5a',False),.6)],'#e3f5e9',150),panel([(god('#e0a800'),.8),(person('#c0392b'),.8),(skanda(),.8)],'#fff3cf',150),panel([(river(144,120),1),(mountain('#6a8a5a',False),.5)],'#dfe9f6',None)],['to Kumāra Parvata','the wedding','the Kumāradhārā']),'The Kukke Subrahmaṇya temple tradition.',['After the victory, in the Karnataka tradition, Skanda came with his brother Gaṇeśa to <b>Kumāra Parvata</b> in the Western Ghāṭs.','There <b>Indra</b> gave him his daughter <b>Devasenā</b> in marriage.','The wedding took place on <b>Mārgaśīrṣa Śuddha Ṣaṣṭhī</b>: Karnataka’s Subrahmaṇya Ṣaṣṭhī.','Holy waters brought from every river for the wedding flowed together as the <b>Kumāradhārā</b>, the river at Kukke.','Nearby, the serpent king <b>Vāsuki</b> was praying in a cave to escape Garuḍa. Skanda stayed to protect him: that story is '+L('/subramanya/kukke/','Part 3')+'.'],[('z','So Karnataka celebrates the wedding?'),('b','The wedding and the serpent, Zappy. That’s why milk goes to the anthills on this day.')],'A wedding <b>in the Ghāṭs</b>.'),
 verse('v-bhujanga3','Subrahmaṇya Bhujaṅgam, verse 3','The son of Mahādeva on his peacock',['mayūrādhirūḍhaṃ mahāvākyagūḍhaṃ','manohāridehaṃ mahaccittageham','mahīdevadevaṃ mahāvedabhāvaṃ','mahādevabālaṃ bhaje lokapālam'],svg(200,150,'Skanda seated on his peacock',f'<rect width="200" height="150" fill="#e3eaf3"/>'+g(100,140,1.4,peacock())+g(100,110,1,skanda())),'I worship the protector of the world, the child of Mahādeva: mounted on the peacock, hidden in the great sayings of the Veda, of captivating form, dwelling in great minds, god of the brahmins, the very meaning of the Veda.',[('mayūra-adhirūḍham','mounted on the peacock'),('mahāvākya-gūḍham','hidden in the great Vedic sayings'),('manohāri-deham','of captivating form'),('mahat-citta-geham','dwelling in great minds'),('mahādeva-bālam','child of Mahādeva'),('loka-pālam','protector of the world')],'<b>Śaṅkara at Tiruccendūr.</b> Tradition says Ādi Śaṅkara, ill and in pain, came to Tiruccendūr and, seeing Murugan, burst into this hymn in the gliding <i>bhujaṅga</i> (serpent) metre. This verse paints the god of the day: the boy on the peacock that was once a demon. The Bhujaṅgam is widely sung on Ṣaṣṭhī.',k='The child of Śiva <b>on his peacock</b>.',note='Text as on shlokam.org (Subramanya Bhujangam), verse 3; the full hymn is on sanskritdocuments.org.'),
 reading('karnataka','HOW KARNATAKA KEEPS IT','At home and at the anthill',svg(560,170,'Women pouring milk at an anthill under a peepal tree, a boy being fed, and a chariot in the distance',f'<rect width="560" height="170" fill="#cfe0d8"/>'+'<rect y="140" width="560" height="30" fill="#a8c890"/>'+g(140,150,1.2,tree())+g(150,150,1,anthill())+g(240,150,1,person('#c0392b'))+g(350,150,1,child())+g(370,130,.8,plate())+g(480,150,1,chariot())),['<b>Fast.</b> Many fast till the pūjā, or keep one meal.','<b>The anthill.</b> Milk, turmeric, flowers and a lamp are offered at the cobra’s anthill (<i>huttu</i>) or at nāga stones under a peepal tree: Subrahmaṇya in Karnataka is the protector of serpents (read our '+L('/festivals/naga-panchami/','Nāga Pañcamī')+' article).','<b>Feeding a boy.</b> In many homes a young bachelor boy (<i>brahmacārī</i>) is fed and honoured as the boy-god <b>Kumāra</b>, and given new clothes.','<b>Temples.</b> Chariot festivals at <b>Kukke Subrahmaṇya</b> and Subrahmaṇya shrines across the state; Mysuru’s Subrahmaṇya temples, such as the one at Bannimaṇṭap, keep the day. It is also a day to fulfil vows made for children, health and freedom from “sarpa doṣa”.'],[('z','Why feed a boy?'),('b','Kumāra means the boy, Zappy. Feed a boy, feed the god.')],'Milk at the anthill, <b>food for Kumāra</b>.'),
 reading('kukkeday','ṢAṢṬHĪ AT KUKKE','The Brahmaratha and the Ghāṭs',svg(560,170,'A huge wooden chariot pulled by crowds below forested hills, with a river',f'<rect width="560" height="170" fill="#e3f5e9"/>'+''.join(g(x,140,1,mountain('#5a7a4a',False)) for x in (60,180,420,520))+'<path d="M0 150 q280 -10 560 0 v20 h-560z" fill="#8fb8de"/>'+g(300,150,1.8,chariot())+''.join(g(x,155,.5,person('#2a5aa8')) for x in range(120,260,20))),['<b>Campā Ṣaṣṭhī.</b> At <b>Kukke Subrahmaṇya</b> in the Western Ghāṭs, the Ṣaṣṭhī of Mārgaśīrṣa is the great annual festival, with the <b>Brahmaratha</b>, the temple’s great chariot, pulled through the street by thousands.','<b>The days before.</b> Processions, smaller chariots and illuminated nights lead up to it; pilgrims bathe in the Kumāradhārā before darśan.','<b>Vows.</b> Kukke is Karnataka’s great shrine for serpent vows and rites, and many fulfil them at Ṣaṣṭhī.','<b>The full story.</b> Vāsuki, Garuḍa and the cave, the temple and its rites: '+L('/subramanya/kukke/','Part 3, Kukke Subrahmaṇya')+'.'],[('z','How big is the chariot?'),('b','Big enough that it takes a whole town to move it, Zappy. That’s the point.')],'A whole town <b>pulls the chariot</b>.'),
 verse('v-bhujanga2','Subrahmaṇya Bhujaṅgam, verse 2','I know nothing; the six-faced one shines in me',['na jānāmi śabdaṃ na jānāmi cārthaṃ','na jānāmi padyaṃ na jānāmi gadyam','cid ekā ṣaḍāsyā hṛdi dyotate me','mukhān niḥsarante giraś cāpi citram'],svg(200,150,'A seated poet with light rising from his heart in the shape of six small faces',f'<rect width="200" height="150" fill="#e3eaf3"/>'+g(100,140,1.2,sage('#ff8c1a'))+''.join(f'<circle cx="{100+30*__import__("math").cos(k*1.047):.1f}" cy="{60+18*__import__("math").sin(k*1.047):.1f}" r="5" fill="#ffd60a"/>' for k in range(6))),'I know no words, I know no meanings, I know no verse, I know no prose. Yet a single consciousness with six faces shines in my heart, and wondrous words pour out of my mouth.',[('na jānāmi','I do not know'),('śabdam','words'),('artham','meaning'),('cit ekā','one consciousness'),('ṣaḍ-āsyā','six-faced'),('giraḥ','words, speech')],'<b>Humility.</b> The great Śaṅkara says he knows nothing of poetry: the six-faced god speaks through him. It is the perfect verse for a day about pride defeated.',k='Pride gone, <b>the god speaks</b>.',note='Text as given at mantra.tips and sanskritdocuments.org (Subrahmaṇya Bhujaṅgam, verse 2), set in IAST.'),
 reading('meaning','WHAT ṢAṢṬHĪ TEACHES','The vel and the peacock',svg(560,150,'The vel standing upright with a peacock and rooster on either side',f'<rect width="560" height="150" fill="#e3eaf3"/>'+g(280,140,1.6,vel())+g(180,140,1.2,peacock())+g(380,140,1.2,rooster())),['<b>The boy-god.</b> The strongest of the gods is a boy: courage and clarity, not size, win the war. (Interpretation.)','<b>The vel.</b> His spear pierces mountains and illusions; many read it as discrimination, the sharp knowledge that sees through pride. (Interpretation.)','<b>Mercy.</b> The demon is split, not destroyed: what was pride becomes the vehicle and the flag. The enemy within is tamed and put to work.','<b>Protector.</b> In Karnataka he is above all the protector of serpents and of children: the festival’s anthills and boy-feasts make the god practical.'],[('z','If I could do one thing for Ṣaṣṭhī?'),('b','Say his name six times, Zappy, once for each face, and feed a hungry child.')],'Pride tamed, <b>not destroyed</b>.'),
 end(i,['<b>Ṣaṣṭhī.</b> Skanda’s sixth day: six mothers, six faces, six days of war.','<b>Two festivals.</b> Skanda Ṣaṣṭhī in Aippasi; Subrahmaṇya Ṣaṣṭhī in Mārgaśīrṣa.','<b>War.</b> Tāraka and Krauñca; Śūrapadma and the mango tree; Sūrasaṃhāram.','<b>Karnataka.</b> The wedding at Kumāra Parvata; milk at anthills; Kukke’s Brahmaratha.','<b>Verses.</b> Subrahmaṇya Bhujaṅgam 2 and 3.'],'Part 3 tells Kukke Subrahmaṇya: Vāsuki, Garuḍa and the serpent’s refuge.','The Ṣaṣṭhī story'),
 sources([('Stories:','Skanda and Śiva Purāṇas (birth, Tāraka); the Tamil Kanda Purāṇam (Śūrapadma, the mango tree); Kukke temple tradition (the wedding, Kumāradhārā). Bhujaṅgam verses from shlokam.org, mantra.tips and sanskritdocuments.org.'),('Customs:','Ṣaṣṭhī dates and names, Sūrasaṃhāram, Campā Ṣaṣṭhī at Jejuri, Karnataka customs, as summarised in our earlier guide from almanac, temple and press sources.')],'Krauñca as mountain or demon (tellings differ); the origin of “Campā” (explanations differ); the six-enemies reading (popular teaching); temple-specific dates and events (may change).','Interpretations are marked as such.')]
